/**
 * Expand config/verses.json with established translations.
 *
 * Run this ahead of time, never during a sermon — the verse library is read
 * from disk at startup so the Friday path touches no external service.
 *
 *   node scripts/fetch-verses.js 2:153 65:2 94:5-6 18:1-10
 *   node scripts/fetch-verses.js --surah 103
 *
 * Translations used:
 *   French  — Muhammad Hamidullah
 *   English — Saheeh International
 *
 * Both are widely used and neither is generated by a machine. That is the
 * entire point: the app substitutes an established translation rather than
 * producing a new rendering of scripture.
 */

import { readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';

const API = 'https://api.alquran.cloud/v1';
const OUT = new URL('../config/verses.json', import.meta.url);

const WANT = {
  ar: { language: 'ar', match: /uthmani/i },
  fr: { language: 'fr', match: /hamidullah/i },
  en: { language: 'en', match: /sahih|saheeh/i },
};

async function get(path) {
  const res = await fetch(`${API}${path}`);
  if (!res.ok) throw new Error(`${path} -> ${res.status}`);
  const body = await res.json();
  if (body.code !== 200) throw new Error(`${path} -> ${body.status}`);
  return body.data;
}

/**
 * Resolve edition identifiers from the API rather than hardcoding them, so
 * this keeps working if the catalogue is renamed.
 */
async function resolveEditions() {
  const all = await get('/edition');
  const chosen = {};

  for (const [key, want] of Object.entries(WANT)) {
    const hit = all.find(
      (e) => e.language === want.language && want.match.test(e.identifier)
    ) || all.find((e) => e.language === want.language && want.match.test(e.name || ''));

    if (!hit) {
      throw new Error(
        `Could not find a ${want.language} edition matching ${want.match}. ` +
        `List them with: curl ${API}/edition | grep ${want.language}`
      );
    }
    chosen[key] = hit.identifier;
    console.log(`  ${key}: ${hit.identifier}  (${hit.englishName || hit.name})`);
  }

  return chosen;
}

/** "2:153" or "65:2-3" -> [{surah, ayah}, ...] */
function expandRef(ref) {
  const [surahPart, ayahPart] = ref.split(':');
  const surah = Number(surahPart);
  if (!ayahPart) throw new Error(`Reference needs an ayah: ${ref}`);

  const [from, to] = ayahPart.split('-').map(Number);
  const out = [];
  for (let a = from; a <= (to || from); a += 1) out.push({ surah, ayah: a });
  return out;
}

async function fetchAyah(surah, ayah, editions) {
  const key = `${surah}:${ayah}`;
  const [ar, fr, en] = await Promise.all([
    get(`/ayah/${key}/${editions.ar}`),
    get(`/ayah/${key}/${editions.fr}`),
    get(`/ayah/${key}/${editions.en}`),
  ]);
  return { ar: ar.text, fr: fr.text, en: en.text };
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length === 0) {
    console.log('Usage: node scripts/fetch-verses.js 2:153 65:2-3 [--surah 103]');
    process.exit(1);
  }

  console.log('Resolving editions…');
  const editions = await resolveEditions();

  const refs = [];
  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === '--surah') {
      const n = Number(args[i + 1]);
      const surah = await get(`/surah/${n}/${editions.ar}`);
      refs.push(`${n}:1-${surah.numberOfAyahs}`);
      i += 1;
    } else {
      refs.push(args[i]);
    }
  }

  const existing = existsSync(OUT) ? JSON.parse(await readFile(OUT, 'utf8')) : [];
  const byRef = new Map(existing.map((v) => [v.ref, v]));

  for (const ref of refs) {
    const parts = expandRef(ref);

    // A multi-ayah reference is stored as one entry, because that is how it
    // is spoken — a khutbah quotes a passage, not an isolated ayah, and the
    // matcher needs the whole passage as one unit.
    const pieces = [];
    for (const { surah, ayah } of parts) {
      pieces.push(await fetchAyah(surah, ayah, editions));
      process.stdout.write('.');
    }

    byRef.set(ref, {
      ref,
      surah: parts[0].surah,
      ayah: parts[0].ayah,
      ar: pieces.map((p) => p.ar).join(' '),
      fr: pieces.map((p) => p.fr).join(' '),
      en: pieces.map((p) => p.en).join(' '),
    });

    console.log(` ${ref}`);
  }

  const merged = [...byRef.values()].sort(
    (a, b) => a.surah - b.surah || a.ayah - b.ayah
  );

  await writeFile(OUT, `${JSON.stringify(merged, null, 2)}\n`);
  console.log(`\nverses.json now holds ${merged.length} entries. Restart the server.`);
}

main().catch((err) => {
  console.error(`\nFailed: ${err.message}`);
  process.exit(1);
});
